#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Small constant for vectorization width. We use 4 so that it maps
// cleanly to at least SSE2 on x86 for both float and double.
static constexpr int kVectorWidth = 4;

/**
 * Initialize matrix A as in the original Polybench C code, but using
 * Halide pipelines for both the triangular initialization and the
 * A * A^T positive semi-definite transform.
 *
 * A is laid out as A(j, i) == A[i][j] from the C code.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    // ------------------------------------------------------------------
    // 1) Construct lower-triangular matrix with diagonal 1 (Polybench init)
    // ------------------------------------------------------------------
    //
    // C code:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].

    Func init_tri("init_tri");

    // Equivalent to (DATA_TYPE)(-j % n) / n + 1, with j < n.
    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1 to match the C code.
    init_tri(i, i) = cast<num_t>(1);

    // Schedule: fill the n x n matrix in parallel over rows, with
    // some vectorization along the contiguous x dimension (j).
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, kVectorWidth);

    // Realize directly into the supplied buffer A.
    init_tri.realize(A);

    // ------------------------------------------------------------------
    // 2) Make the matrix positive semi-definite: B = A * A^T
    // ------------------------------------------------------------------
    //
    // C code:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // Mapping:
    //  B[r][s] -> B_func(s, r)
    //  A[r][t] -> A_param(t, r)
    //  A[s][t] -> A_param(t, s)

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule for good locality and parallelism:
    //  - parallelize over rows (r)
    //  - vectorize over columns (s) which are contiguous in memory
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, kVectorWidth);
    B_func.update()
        .parallel(r)
        .vectorize(s, kVectorWidth);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A. This preserves the original Polybench semantics
    // (A is overwritten with B).
    A.copy_from(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // Convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code (but via Halide).
    init_array(n, A);

    // ------------------------------------------------------------------
    // Build a Halide pipeline for the inner dot-product used in Cholesky
    // ------------------------------------------------------------------
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // Mapping to buffer indices A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // The algorithm has loop-carried dependencies in i and j, so we keep
    // the i/j loops on the host (as recommended for DP-style algorithms),
    // but we express the inner k-accumulation as a Halide reduction.
    //
    // For fixed (i, j), define:
    //    sum_ij = sum_{k=0}^{j-1} A[i][k] * A[j][k]
    //           = sum_{k=0}^{j-1} A(k, i) * A(k, j)
    //
    // Then:
    //    A(j, i) = (A(j, i) - sum_ij) / A(j, j)
    //
    // For the diagonal:
    //    sum_ii = sum_{k=0}^{i-1} A[i][k]^2
    //           = sum_{k=0}^{i-1} A(k, i) * A(k, i)
    //           = sum_{k=0}^{i-1} A(k, i) * A(k, i)  (j = i case)
    //
    //    A(i, i) = sqrt(A(i, i) - sum_ii)
    //
    // We implement a generic dot-product Func parameterized by i and j
    // which computes the sum over k, and invoke it from the host loops.

    ImageParam A_image(type_of<num_t>(), 2, "A_image");
    A_image.set(A); // Bind to underlying A buffer; updates are visible.

    Param<int> i_param("i_param");
    Param<int> j_param("j_param");

    // One-dimensional dummy index to hold a single scalar result.
    Var idx("idx");

    // Reduction domain: k runs from 0 to j_param-1 (runtime extent).
    RDom k(0, j_param, "k");

    Func dot("cholesky_dot");
    // Initialize the scalar output at idx == 0 to zero.
    dot(idx) = cast<num_t>(0);
    // Accumulate A(k, i) * A(k, j) for k in [0, j_param).
    dot(idx) += A_image(k, i_param) * A_image(k, j_param);

    // Schedule: this is just a 1-element output, so a simple schedule
    // is fine; the heavy work is in the k-loop. We keep it compute_root
    // so that each call to realize() reuses the compiled code with new
    // parameter values.
    dot.compute_root();

    // Reuse a single 1D buffer to hold the scalar result, avoiding
    // repeated allocations inside the timing loop.
    Halide::Buffer<num_t> dot_buf(1);

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel.
    // Compilation/JIT of Halide pipelines happens before we start the
    // timer so that we only measure numerical work.
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute sum_{k=0}^{j-1} A(k, i) * A(k, j) using Halide.
            num_t sum_ij = static_cast<num_t>(0);
            if (j > 0) {
                dot.realize(dot_buf);
                sum_ij = dot_buf(0);
            }

            // Update A(j, i) = (A(j, i) - sum_ij) / A(j, j)
            num_t a_ji = A(j, i);
            num_t a_jj = A(j, j);
            a_ji = (a_ji - sum_ij) / a_jj;
            A(j, i) = a_ji;
        }

        // Diagonal element at (i, i).
        if (i > 0) {
            // sum_{k=0}^{i-1} A(k, i) * A(k, i)
            j_param.set(i);
            dot.realize(dot_buf);
            num_t sum_ii = dot_buf(0);

            A(i, i) -= sum_ii;
        }

        // Final square root on the diagonal element.
        A(i, i) = static_cast<num_t>(
            std::sqrt(static_cast<double>(A(i, i)))
        );
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
