#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize matrix A as in the original Polybench C code, then make it
// symmetric positive (semi-)definite by computing A := A * A^T. All of
// this is done with Halide Funcs and scheduled for locality and parallelism.
//
// Note: we keep the logical layout A(j, i) == A[i][j] from the C code.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    // Use the host target only to query natural vector width.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    // ------------------------------------------------------------
    // 1. Build the lower-triangular matrix with diagonal 1.
    //    C code:
    //      for (i = 0; i < n; i++) {
    //        for (j = 0; j <= i; j++)
    //          A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //        for (j = i+1; j < n; j++)
    //          A[i][j] = 0;
    //        A[i][i] = 1;
    //      }
    //
    //    Mapping to Halide: A(j, i) corresponds to A[i][j].
    // ------------------------------------------------------------
    Func init_tri("init_tri");

    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower triangle (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1.
    init_tri(i, i) = cast<num_t>(1);

    // Schedule: row-major traversal, parallel in the outer dimension (rows),
    // vectorized in the inner dimension (columns).
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize directly into the provided buffer A.
    init_tri.realize(A);

    // ------------------------------------------------------------
    // 2. Make the matrix symmetric positive semi-definite:
    //
    //    B[r][s] = sum_t A[r][t] * A[s][t];
    //    A[r][s] = B[r][s];
    //
    //    This is B = A * A^T, where A is n x n lower-triangular.
    //    We implement this as a Halide reduction over t.
    // ------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param_init");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    // A[r][t] -> A_param(t, r);  A[s][t] -> A_param(t, s)
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule: compute the full matrix at root, parallelize across
    // the slow (row) dimension and vectorize across the fast
    // (column) dimension for good cache and SIMD utilization.
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, vec_width);

    B_func.update()
        .parallel(r)
        .vectorize(s, vec_width);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (O(n^2), negligible vs. O(n^3) matmul).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code
    // and make it symmetric positive semi-definite.
    init_array(n, A);

    // ------------------------------------------------------------------
    // Build Halide helper pipelines for Cholesky factorization.
    //
    // We use a standard column-oriented Cholesky algorithm, updating A
    // in place to contain the Cholesky factor L (lower-triangular):
    //
    //   for (k = 0..n-1) {
    //     // Diagonal element L[k][k]
    //     A[k][k] -= sum_{j=0..k-1} A[k][j]^2;
    //     A[k][k] = sqrt(A[k][k]);
    //
    //     // Off-diagonal elements in column k
    //     for (i = k+1..n-1) {
    //       A[i][k] -= sum_{j=0..k-1} A[i][j] * A[k][j];
    //       A[i][k] /= A[k][k];
    //     }
    //   }
    //
    // We implement the inner dot-products and column update with Halide
    // Funcs, driven by an outer C++ loop over k. This respects the
    // loop-carried dependencies while still giving Halide substantial
    // work to optimize (vectorization, parallelism, locality).
    //
    // Remember our layout: A(i_row, j_col) in C is A(j_col, i_row) in
    // the Buffer. So L[i][k] lives at A(k, i).
    // ------------------------------------------------------------------

    // ImageParam view over the current matrix state; it is updated in-place
    // in the Buffer A, but is read-only from the perspective of each Halide
    // pipeline invocation.
    ImageParam A_param(type_of<num_t>(), 2, "A_param_factor");
    A_param.set(A);

    // k is the current column index of the Cholesky algorithm.
    Param<int> k_param("k");

    // L[k][k] for the current column, passed as a scalar Param into the
    // column-update pipeline.
    Param<num_t> diag_param("diag_param");

    Var i("i");

    // Target and natural vector width for scheduling.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size<num_t>();

    // ---------------- Diagonal element pipeline ----------------
    //
    // Computes:
    //   diag_val() = sqrt( A[k][k] - sum_{j=0..k-1} A[k][j]^2 )
    //
    // In our Buffer layout:
    //   A[k][k]      -> A_param(k_param, k_param)
    //   A[k][j]      -> A_param(j, k_param)
    //
    RDom r_diag(0, k_param, "r_diag");

    Func diag_acc("diag_acc");
    diag_acc() = cast<num_t>(0);
    diag_acc() += A_param(r_diag, k_param) * A_param(r_diag, k_param);

    Func diag_val("diag_val");
    diag_val() = Halide::sqrt(A_param(k_param, k_param) - diag_acc());

    // Scheduling: scalar reduction; no vectorization possible, but we
    // hoist it to root to keep the IR simple.
    diag_acc.compute_root();
    diag_val.compute_root();

    // ---------------- Column update pipeline ----------------
    //
    // For fixed k and known L[k][k], compute all L[i][k] for i = 0..n-1:
    //
    //   sum_col(i) = sum_{j=0..k-1} A[i][j] * A[k][j]
    //   col_val(i) = (A[i][k] - sum_col(i)) / L[k][k]
    //
    // We then only use col_val(i) for i > k.
    //
    // In Buffer layout:
    //   A[i][j]  -> A_param(j, i)
    //   A[k][j]  -> A_param(j, k_param)
    //   A[i][k]  -> A_param(k_param, i)
    //
    RDom r_col(0, k_param, "r_col");

    Func sum_col("sum_col");
    sum_col(i) = cast<num_t>(0);
    sum_col(i) += A_param(r_col, i) * A_param(r_col, k_param);

    Func col_val("col_val");
    col_val(i) = (A_param(k_param, i) - sum_col(i)) / diag_param;

    // Schedule: sum_col and col_val are 1D over i. We parallelize across
    // i (rows) and vectorize along the inner i dimension. The reduction
    // is over r_col only, so parallelizing the pure variable i is safe.
    sum_col
        .compute_root()
        .vectorize(i, vec_width);

    sum_col.update()
        .parallel(i)
        .vectorize(i, vec_width);

    col_val
        .compute_root()
        .vectorize(i, vec_width);

    // JIT-compile helper pipelines ahead of timing to avoid measuring JIT time.
    diag_val.compile_jit(target);
    col_val.compile_jit(target);

    // Temporary buffer reused for each column's L[i][k] values.
    Halide::Buffer<num_t> col_buffer(n);

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel.
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Column-oriented Cholesky factorization using the Halide pipelines
    // defined above for the inner work.
    for (int k = 0; k < n; ++k) {
        // Bind current column index for both pipelines.
        k_param.set(k);

        // ---- 1. Compute diagonal element L[k][k]. ----
        {
            Halide::Buffer<num_t> diag_buf = diag_val.realize();
            num_t diag = diag_buf();

            // Store back into A(k, k) in-place.
            A(k, k) = diag;

            // Make it available to the column update pipeline.
            diag_param.set(diag);
        }

        // ---- 2. Compute off-diagonal elements L[i][k] for i > k. ----
        {
            // Compute the whole column analytically; we'll only use i > k.
            col_val.realize(col_buffer);

            for (int i_row = k + 1; i_row < n; ++i_row) {
                // L[i][k] lives at A(k, i_row) under our layout.
                A(k, i_row) = col_buffer(i_row);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
