#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize matrix A as in the original Polybench C code, but use Halide
// with an explicit schedule to improve locality and parallelism.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is laid out as A(j, i) == A[i][j] from the C code.
    Var i("i"), j("j");

    // Query a reasonable vector width for this machine and element type.
    Target target = get_host_target();
    const int vec_width = Halide::natural_vector_size<num_t>(target);

    // --------------------------------------------------------------------
    // 1. Construct the initial lower-triangular matrix (with diagonal 1)
    //    exactly as in the Polybench init_array, but in Halide.
    //
    // C code:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].
    // --------------------------------------------------------------------
    Func init_tri("init_tri");

    // (-j % n) / n + 1, promoted to num_t
    Expr j_mod_n = j % n;
    Expr val = cast<num_t>(-j_mod_n);
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1 to exactly match the C code.
    init_tri(i, i) = cast<num_t>(1);

    // Schedule: fill the matrix in parallel by rows (i), and vectorize
    // across the inner, contiguous dimension (j).
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffer A.
    init_tri.realize(A);

    // --------------------------------------------------------------------
    // 2. Make the matrix positive semi-definite:
    //
    // C code:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // This is B = A * A^T, where A is n x n lower-triangular.
    //
    // Mapping to Halide indices:
    //   A[r][t] -> A_param(t, r)  (column t, row r)
    //   A[s][t] -> A_param(t, s)  (column t, row s)
    //   B[r][s] -> B_func(s, r)   (column s, row r)
    // --------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule for B = A * A^T:
    // - compute_root: materialize the full SPD matrix once.
    // - parallelize across the outer dimension r (rows).
    // - vectorize across s (contiguous x-dimension) for good SIMD usage.
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, vec_width);

    B_func
        .update()
        .parallel(r)
        .vectorize(s, vec_width);

    // Realize into a temporary buffer B. We keep A_param as read-only
    // and write results into B to avoid aliasing between input and output.
    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (A now holds a symmetric positive semi-definite
    // matrix as expected by the Cholesky factorization).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

