    // Main computational kernel translated directly, operating on the Buffer.
    //
    // Original C:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // The algorithm has strong loop-carried dependencies between i and j
    // (each new element in row i depends on previously computed elements
    // in the same row), which makes it ill-suited for a single, fully
    // fused Halide reduction pipeline. In accordance with the guidelines
    // for such recurrences, we keep the outer loops in C++ but operate
    // directly on the Halide::Buffer to preserve cache-friendly access
    // patterns (k is the contiguous dimension).
    for (int i = 0; i < n; i++) {
        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            // A(j, i) -= sum_{k=0}^{j-1} A(k, i) * A(k, j)
            for (int k = 0; k < j; k++) {
                A(j, i) -= A(k, i) * A(k, j);
            }
            // Divide by the pivot on column j.
            A(j, i) /= A(j, j);
        }

        // Diagonal element.
        // A(i, i) -= sum_{k=0}^{i-1} A(k, i)^2
        for (int k = 0; k < i; k++) {
            A(i, i) -= A(k, i) * A(k, i);
        }
        // A(i, i) = sqrt(A(i, i))
        A(i, i) = static_cast<num_t>(std::sqrt(static_cast<double>(A(i, i))));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

