    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // Directly expressing these loop-carried dependencies as a single
    // Halide Func is illegal (Halide forbids self-references at
    // different coordinates). Instead, we implement an *outer-product*
    // Cholesky variant, which is mathematically equivalent:
    //
    // for (k = 0; k < n; k++) {
    //   A[k][k] = sqrt(A[k][k]);
    //   for (i = k+1; i < n; i++)
    //     A[i][k] /= A[k][k];
    //   for (j = k+1; j < n; j++)
    //     for (i = j; i < n; i++)
    //       A[i][j] -= A[i][k] * A[j][k];
    // }
    //
    // We implement each iteration k as a *pure Halide transform* that
    // takes the current matrix A_in and produces a new matrix A_out
    // with:
    //   - updated pivot A[k][k] = sqrt(A[k][k]),
    //   - updated column A[i][k] for i > k,
    //   - updated trailing submatrix A[i][j] for i >= j > k,
    //     using only values from A_in.
    //
    // This outer-product formulation is:
    //   L_kk      = sqrt(A_in[k][k])
    //   L_ik      = A_in[i][k] / L_kk
    //   A_out[i][j] = A_in[i][j] - L_ik * L_jk  (for i >= j > k)
    //
    // Expressed in Halide's coordinate system (A(j, i) == A[i][j]):
    //   pivot       at (k, k)
    //   column k    at (k, i) with i > k
    //   trailing    at (j, i) with i >= j > k
    //
    // All of this is done *without* self-references: A_out only reads
    // from A_in, which lets us JIT-compile and aggressively optimize
    // each step with Halide.

    // Halide pipeline for one Cholesky outer-product step.
    ImageParam A_in(type_of<num_t>(), 2, "A_in");  // current matrix
    Param<int> k_param("k");                       // current pivot index k
    Param<num_t> diag_sqrt_param("diag_sqrt");     // sqrt(A_in(k,k)) for this step

    Var j("j"), i("i");
    Func cholesky_step("cholesky_step");

    // Current value.
    Expr val = A_in(j, i);
    Expr diag = diag_sqrt_param;

    // Predicates for the various regions we update.
    Expr is_pivot   = (j == k_param) && (i == k_param);
    Expr is_column  = (j == k_param) && (i >  k_param);
    Expr is_trail   = (j >  k_param) && (i >= j);

    // Column k elements L_ik and L_jk (in terms of A_in and diag).
    Expr L_i_k = A_in(k_param, i) / diag;
    Expr L_j_k = A_in(k_param, j) / diag;

    // Trailing submatrix update.
    Expr updated = A_in(j, i) - L_i_k * L_j_k;

    // Combine into a single select expression.
    cholesky_step(j, i) =
        select(is_pivot,
               // A[k][k] = sqrt(A[k][k])
               diag,
               is_column,
               // A[i][k] /= sqrt(A[k][k])
               A_in(j, i) / diag,
               is_trail,
               // A[i][j] -= L_ik * L_jk
               updated,
               // Unchanged elsewhere (including upper triangle i < j).
               val);

    // Schedule for the Cholesky step:
    //  - compute_root: evaluate entire matrix per step
    //  - parallelize across rows (i) and vectorize across columns (j)
    {
        Target target = get_host_target();
        const int vec = target.natural_vector_size(type_of<num_t>());

        cholesky_step
            .compute_root()
            .parallel(i)
            .vectorize(j, vec);

        // Pre-JIT to keep compilation cost out of the timed section.
        cholesky_step.compile_jit(target);
    }

    // Double-buffering for A across Cholesky steps.
    Halide::Buffer<num_t, 2> A_tmp(n, n);
    Halide::Buffer<num_t, 2> *A_curr = &A;
    Halide::Buffer<num_t, 2> *A_next = &A_tmp;

    // Time the Cholesky factorization kernel.
    auto start = std::chrono::high_resolution_clock::now();

    // Perform n outer-product Cholesky steps.
    for (int k = 0; k < n; k++) {
        // Diagonal value at (k, k) in current matrix.
        num_t diag_val = (*A_curr)(k, k);

        // Match the original numeric behavior:
        // A[i][i] = (DATA_TYPE) sqrt((double) A[i][i]);
        num_t diag_sqrt =
            static_cast<num_t>(std::sqrt(static_cast<double>(diag_val)));

        // Bind current matrix and parameters for this step.
        A_in.set(*A_curr);
        k_param.set(k);
        diag_sqrt_param.set(diag_sqrt);

        // Realize updated matrix into A_next.
        cholesky_step.realize(*A_next);

        // Swap current and next for the next iteration.
        Halide::Buffer<num_t, 2> *tmp = A_curr;
        A_curr = A_next;
        A_next = tmp;
    }

    // Make sure A refers to the final matrix for printing below.
    if (A_curr != &A) {
        A = *A_curr;  // share the underlying storage, no data copy
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
