#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Tunable tiling parameters for the n×n symmetric positive-definite
// construction (matrix multiply). Adjust if you want to retune for
// different cache sizes.
static constexpr int MM_TILE_R = 32;
static constexpr int MM_TILE_S = 32;

// Initialize matrix A as in the original Polybench C code,
// but do the heavy work with optimized Halide pipelines.
static void init_array(int n, Halide::Buffer<num_t, 2> &A) {
    // A is laid out as A(j, i) == A[i][j] from the C code.
    Var i("i"), j("j");

    // ------------------------------------------------------------------
    // 1. Construct the initial lower-triangular matrix with diagonal 1
    //    exactly as the Polybench init_array does.
    //
    // C reference:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].
    // ------------------------------------------------------------------
    Func init_tri("init_tri");

    // Compute the Polybench value: (-j % n) / n + 1
    Expr j_mod_n   = j % n;
    Expr n_expr    = cast<num_t>(Expr(n));
    Expr one_expr  = cast<num_t>(Expr(1));
    Expr zero_expr = cast<num_t>(Expr(0));

    Expr val = cast<num_t>(-j_mod_n) / n_expr + one_expr;

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, zero_expr);

    // Explicitly set the diagonal to 1 (matches original C).
    init_tri(i, i) = one_expr;

    // Basic locality- and parallel-friendly schedule for init_tri:
    //  - Parallelize rows (i).
    //  - Vectorize along j, the contiguous (stride-1) dimension.
    Target t = get_host_target();
    const int vec_width = t.natural_vector_size(type_of<num_t>());

    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize directly into the provided buffer A.
    init_tri.realize(A);

    // ------------------------------------------------------------------
    // 2. Make the matrix symmetric positive semi-definite:
    //
    //    B[r][s] = sum_t A[r][t] * A[s][t];
    //    A[r][s] = B[r][s];
    //
    // which is B = A * A^T, with A lower-triangular n×n.
    //
    // With our layout A(j, i) == A[i][j]:
    //   A[r][t] -> A_param(t, r)
    //   A[s][t] -> A_param(t, s)
    // and we compute B(s, r) == B[r][s].
    // ------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t_red(0, n, "t_red");

    Func B_func("B_func");
    B_func(s, r) = zero_expr;
    B_func(s, r) += A_param(t_red, r) * A_param(t_red, s);

    // Schedule for B_func:
    //  - Compute at root so we can tile/parallelize.
    //  - Tile the (s, r) space to improve cache locality.
    //  - Parallelize tiles across cores.
    //  - Vectorize within tiles along s (stride-1 dimension).
    Var so("so"), ro("ro"), si("si"), ri("ri"), tile_index("tile_index");

    B_func
        .compute_root()
        .tile(s, r, so, ro, si, ri, MM_TILE_S, MM_TILE_R)
        .fuse(so, ro, tile_index)
        .parallel(tile_index)
        .vectorize(si, vec_width);

    // For the reduction update:
    //  - Make 's' the innermost loop and vectorize across it.
    B_func.update()
        .reorder(s, r, t_red)  // loops: for t_red, for r, for s
        .vectorize(s, vec_width);

    // Realize B = A * A^T.
    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (n^2 work, negligible vs. n^3 multiply).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

// Optimized in-place Cholesky factorization on A, using the same
// mapping A(j, i) == A[i][j]. This is still expressed in plain C++
// because the algorithm is strongly sequential in both i and j, which
// makes it a poor fit for a single fused Halide pipeline. We instead
// focus on improving locality and arithmetic efficiency of the
// original Polybench kernel.
static void cholesky_in_place(int n, Halide::Buffer<num_t, 2> &A) {
    // Outer loop over the row/column index i.
    for (int i = 0; i < n; i++) {
        // ------------------------------------------------------------------
        // Off-diagonal elements in row i:
        //
        // Original (mapped) form:
        //   for (j = 0; j < i; j++) {
        //     for (k = 0; k < j; k++) {
        //       A(j, i) -= A(k, i) * A(k, j);
        //     }
        //     A(j, i) /= A(j, j);
        //   }
        //
        // We rewrite this to accumulate the inner product into a local
        // variable 'sum' to reduce the number of loads and stores of
        // A(j, i).
        // ------------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            num_t sum = static_cast<num_t>(0);

            // Dot product over k < j: sum += A(k, i) * A(k, j)
            for (int k = 0; k < j; k++) {
                const num_t a_ki = A(k, i);  // contiguous in k
                const num_t a_kj = A(k, j);  // contiguous in k
                sum += a_ki * a_kj;
            }

            // Update single off-diagonal entry using the accumulated sum.
            num_t a_ji = A(j, i);
            a_ji -= sum;
            a_ji /= A(j, j);
            A(j, i) = a_ji;
        }

        // ------------------------------------------------------------------
        // Diagonal element A(i, i):
        //
        // Original (mapped) form:
        //   for (k = 0; k < i; k++) {
        //     A(i, i) -= A(k, i) * A(k, i);
        //   }
        //   A(i, i) = sqrt(A(i, i));
        //
        // Again, accumulate first to minimize repeated loads/stores.
        // ------------------------------------------------------------------
        num_t diag_sum = static_cast<num_t>(0);
        for (int k = 0; k < i; k++) {
            const num_t a_ki = A(k, i);
            diag_sum += a_ki * a_ki;
        }

        num_t diag = A(i, i) - diag_sum;
        // Use double-precision sqrt for better accuracy if num_t is float.
        diag = static_cast<num_t>(std::sqrt(static_cast<double>(diag)));
        A(i, i) = diag;
    }
}

